const taskSchema = z.strictObject({
  taskId: hashSchema,
  key: z.string(),
  namespace: z.string(),
  diffSha256: hashSchema,
  identity: z.string().nullable(),
  at: z.string().nullable(),
  model: z.string().nullable(),
  arm: z.string(),
  base: z.string().nullable(),
  status: z.string(),
