/**
 * Shared test fixtures for the CLI suites. `_`-prefixed so vitest's *.test.mjs glob never picks
 * it up as a suite. Collapses the tmp-repo + subprocess-runner + cleanup boilerplate that every
 * subprocess-style CLI test repeated verbatim.
 */
import {
  type ChildProcess,
  execFileSync as nodeExecFileSync,
  spawnSync as nodeSpawnSync,
  spawn,
} from 'node:child_process';
import { once } from 'node:events';
import {
  chmodSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { availableParallelism, loadavg, tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { formatLoad } from '../../vitest.global-setup.mjs';
import { shQuote } from '../lib/ship/redact-secrets.mts';

/** Absolute path to the devkit CLI entry (cli/index.mjs). */
export const CLI = join(dirname(fileURLToPath(import.meta.url)), '..', 'index.mts');
const TEST_SUBPROCESS = fileURLToPath(new URL('./test-subprocess.mts', import.meta.url));
export const TEST_SUBPROCESS_TIMEOUT_MS = 90_000;
/** Exported alongside the deadline so test-subprocess.test.mts can pin the resolved outer budget. */
export const TEST_SUBPROCESS_CLEANUP_MS = 30_000;
/** review-target.sh echoes DEVKIT_PREFLIGHT_TIMEOUT verbatim, so the ceiling may be fractional. */
const SETUP_CEILING_RE = /hit the ([\d.]+)s ceiling DURING: (\S+)/;
const EPHEMERAL_SHIP_WORKTREE_RE = /devkit-(?:re)?ship-/;

function commandCall(
  command: string,
  argsOrOptions: readonly string[] | Record<string, unknown> | undefined,
  maybeOptions: Record<string, unknown> | undefined,
) {
  const args = Array.isArray(argsOrOptions) ? argsOrOptions : [];
  const options = (Array.isArray(argsOrOptions) ? maybeOptions : argsOrOptions) ?? {};
  const requestedTimeout = options.timeout;
  const timeoutMs =
    typeof requestedTimeout === 'number' && requestedTimeout > 0
      ? requestedTimeout
      : TEST_SUBPROCESS_TIMEOUT_MS;
  return { command, args, options, timeoutMs };
}

/** Exported for `test-subprocess.test.mts`: the shell-handling contract below is invisible to a
 *  behavioural test on any checkout whose path has no spaces, which is every CI runner. */
export function supervisedCommand(
  command: string,
  argsOrOptions: readonly string[] | Record<string, unknown> | undefined,
  maybeOptions: Record<string, unknown> | undefined,
  groupOnly = false,
) {
  const call = commandCall(command, argsOrOptions, maybeOptions);
  // `shell` describes how the SUPERVISED command should run, never the supervisor invocation.
  // Forwarding it to the outer call makes Node join that argv into one unquoted shell string, so
  // TEST_SUBPROCESS's own path splits on the first space in the repo location — a checkout under
  // `.../Personal and learning/devkit` died with `Cannot find module '/Users/benji/Desktop/Personal'`
  // while CI, whose paths have no spaces, stayed green. Wrap the inner command instead.
  // `shell: true` is node's "pick the platform default"; any other truthy value names the shell.
  const { shell, ...options } = call.options;
  const shellPath = shell === true ? '/bin/sh' : String(shell);
  const supervised = shell
    ? [shellPath, '-c', [call.command, ...call.args].join(' ')]
    : [call.command, ...call.args];
  return {
    args: [
      TEST_SUBPROCESS,
      ...(groupOnly ? ['--group-only'] : []),
      String(call.timeoutMs),
      '--',
      ...supervised,
    ],
    options: {
      ...options,
      timeout: call.timeoutMs + TEST_SUBPROCESS_CLEANUP_MS,
    },
  };
}

/**
 * Synchronous test subprocess with a killable child-process boundary. Vitest's testTimeout cannot
 * interrupt Node while spawnSync blocks, so the runner owns the command's complete process tree and
 * returns 124 after a bounded cleanup instead of letting one broken fixture wedge the whole suite.
 */
export const testSpawnSync = ((
  command: string,
  argsOrOptions?: readonly string[] | Record<string, unknown>,
  maybeOptions?: Record<string, unknown>,
) => {
  const supervised = supervisedCommand(command, argsOrOptions, maybeOptions);
  return nodeSpawnSync(process.execPath, supervised.args, supervised.options);
}) as typeof nodeSpawnSync;

/** Exec-style counterpart to testSpawnSync. It retains execFileSync's return/throw contract while
 * routing short leaf commands through the supervisor's process-group kill path. */
export const testExecFileSync = ((
  command: string,
  argsOrOptions?: readonly string[] | Record<string, unknown>,
  maybeOptions?: Record<string, unknown>,
) => {
  const supervised = supervisedCommand(command, argsOrOptions, maybeOptions, true);
  return nodeExecFileSync(process.execPath, supervised.args, supervised.options);
}) as typeof nodeExecFileSync;

/** Whether a PID still refers to a live process. */
export function processAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

const STDERR_TAIL_CHARS = 64 * 1024;

/** Resolve when a fixture path appears, or fail with a path-specific timeout. Given the child that
 * should write it, fail once that child has exited and its stderr has drained, quoting the tail. */
export function waitForPath(path: string, timeoutMs = 30_000, child?: ChildProcess): Promise<void> {
  let stderr = '';
  let stderrClosed = !child?.stderr || child.stderr.closed;
  // Never detached: it keeps the pipe drained so a chatty child cannot block on a full buffer.
  child?.stderr?.on('data', (chunk) => {
    stderr = (stderr + chunk).slice(-STDERR_TAIL_CHARS);
  });
  child?.stderr?.once('close', () => {
    stderrClosed = true;
  });
  return new Promise((resolve, reject) => {
    const started = Date.now();
    const check = (): void => {
      // Read before the path, so a child that wrote the path and then exited still resolves.
      const exit = child && (child.exitCode ?? child.signalCode);
      if (existsSync(path)) {
        resolve();
        return;
      }
      if (exit != null && stderrClosed) {
        reject(new Error(`${path} never appeared: child exited ${exit}\n${stderr}`));
        return;
      }
      if (Date.now() - started >= timeoutMs) {
        const exited = exit == null ? '' : ` (child exited ${exit})`;
        reject(new Error(`timed out waiting for ${path}${exited}${child ? `\n${stderr}` : ''}`));
        return;
      }
      setTimeout(check, 10);
    };
    check();
  });
}

/** Exercise the public-shell-only signal path and assert cleanup waits for the gate hook to exit. */
export async function assertInterruptedGateKeepsWorktree({
  dir,
  env,
  script,
  args,
  listWorktrees,
}) {
  const ready = join(dir, '.signal-hook-ready');
  const result = join(dir, '.signal-hook-result');
  const hook = join(dir, '.husky/_/pre-commit');
  writeFileSync(
    hook,
    [
      '#!/bin/sh',
      'echo ready > "$SIGNAL_HOOK_READY"',
      'trap \'if [ -d "$PWD" ]; then echo present > "$SIGNAL_HOOK_RESULT"; else echo deleted > "$SIGNAL_HOOK_RESULT"; fi; exit 143\' TERM',
      'while :; do sleep 0.1; done',
    ].join('\n'),
  );
  chmodSync(hook, 0o755);

  const child = spawn('/bin/bash', [script, ...args], {
    cwd: dir,
    stdio: ['ignore', 'ignore', 'pipe'],
    env: {
      ...env,
      SHIP_DRY_RUN: '1',
      SHIP_COMMIT_TIMEOUT: '3',
      SIGNAL_HOOK_READY: ready,
      SIGNAL_HOOK_RESULT: result,
    },
  });
  await waitForPath(ready, 15_000, child);
  if (!child.kill('SIGTERM')) throw new Error('could not signal ship shell');
  const [code, signal] = await once(child, 'exit');
  await waitForPath(result, 15_000);

  if (code !== 143 || signal !== null) throw new Error(`unexpected ship exit: ${code}/${signal}`);
  if (readFileSync(result, 'utf8').trim() !== 'present') {
    throw new Error('gate worktree was removed before the interrupted hook exited');
  }
  if (EPHEMERAL_SHIP_WORKTREE_RE.test(listWorktrees())) {
    throw new Error('interrupted ship left an ephemeral worktree behind');
  }
}

/** Whether at least one command is available on PATH, without interpolating names into shell code. */
export function hasAnyCommand(...commands) {
  return commands.some(
    (command) =>
      testSpawnSync('bash', ['-c', 'command -v "$1"', 'devkit-test', command], {
        stdio: 'ignore',
      }).status === 0,
  );
}

// macOS ships bash 3.2 as /bin/bash, which exercises neither dialect split devkit's shell depends on
// (trap-interrupted `wait`, and "${arr[@]}" on an empty array under set -u). null when only 3.2.
export function findModernBash() {
  for (const candidate of ['bash', '/opt/homebrew/bin/bash', '/usr/local/bin/bash']) {
    const probe = testSpawnSync(candidate, ['-c', 'printf %s "${BASH_VERSINFO[0]}"'], {
      encoding: 'utf8',
    });
    if (probe.status === 0 && Number(probe.stdout) >= 4) return candidate;
  }
  return null;
}

const FIXTURE_PKG = { name: 'fx', version: '0.0.0', type: 'module' };

/**
 * Self-cleaning tmp-repo fixtures for one suite:
 *   const { tmpRepo, devkit, cleanup } = tmpRepos('clean-');
 *   afterEach(cleanup);
 *
 * `tmpRepo(pkg?)` makes a fresh tmp dir seeded with a fixture package.json (pass `pkg` for a
 * custom manifest); `devkit(root, ...args)` runs the CLI in it; `cleanup()` rm's every dir made.
 *
 * @param {string} prefix mkdtemp prefix (a per-suite tag, e.g. 'clean-')
 */
export function tmpRepos(prefix) {
  let roots = [];
  const tmpRepo = (pkg = FIXTURE_PKG) => {
    const root = mkdtempSync(join(tmpdir(), prefix));
    roots.push(root);
    writeFileSync(join(root, 'package.json'), JSON.stringify(pkg, null, 2));
    return root;
  };
  const devkit = (root, ...args) =>
    testSpawnSync(process.execPath, [CLI, ...args], { cwd: root, encoding: 'utf8' });
  const cleanup = () => {
    for (const r of roots) rmSync(r, { recursive: true, force: true });
    roots = [];
  };
  return { tmpRepo, devkit, cleanup };
}

/** Parse a consumer repo's written `.devkit/config.json`. */
export const readConfig = (root) =>
  JSON.parse(readFileSync(join(root, '.devkit/config.json'), 'utf8'));

/**
 * A tmp-dir registry for suites that build their OWN repo shapes (overlay/standalone/monorepo) and
 * so can't use `tmpRepos`, but still share cleanup. `mkTmp(prefix)` makes + tracks a tmp dir; the
 * suite fills it however it likes; `cleanup()` rm's them all. Pair with `afterEach(cleanup)`.
 */
export function rootRegistry() {
  const roots = [];
  const mkTmp = (prefix) => {
    const root = mkdtempSync(join(tmpdir(), prefix));
    roots.push(root);
    return root;
  };
  const cleanup = () => {
    for (const r of roots) rmSync(r, { recursive: true, force: true });
    roots.length = 0;
  };
  return { mkTmp, cleanup };
}

/** A HOME whose `.bun/bin` (first on an overlay hook's PATH) holds this checkout's CLI, logging each
 * call to `devkit-calls`, and passing gate bins that log to `gate-calls`: a global devkit install. */
export function devkitHome(home: string): string {
  const bin = join(home, '.bun', 'bin');
  mkdirSync(bin, { recursive: true });
  const devkit = `#!/bin/sh\necho "$*" >> "$HOME/devkit-calls"\nexec node ${shQuote(CLI)} "$@"\n`;
  writeFileSync(join(bin, 'devkit'), devkit, { mode: 0o755 });
  const gate = '#!/bin/sh\necho "${0##*/} $*" >> "$HOME/gate-calls"\n';
  for (const name of ['deterministic', 'comments', 'decisions', 'review', 'ui-evidence'])
    writeFileSync(join(bin, `guard-${name}`), gate, { mode: 0o755 });
  return home;
}

/**
 * Seed a per-session edits ledger for the agents-hooks suites (session-edits-lib.sh). Creates a
 * fixture-LOCAL tmpdir (pass it as TMPDIR to the hook so real machine state never leaks in) and
 * writes `devkit-session-edits/<REPO_KEY>-<sid>` with the given repo-relative paths. REPO_KEY is
 * computed exactly the way the lib does (`pwd -P | cksum`) so the hook resolves the same file.
 * Pass `paths: null` to create the isolated tmpdir WITHOUT a ledger (the no-edits session shape).
 *
 * @param {string} root fixture repo root
 * @param {string} sid session_id the hook payload will carry
 * @param {string[]|null} paths repo-relative edited paths (null → no ledger)
 * @returns {string} the tmpdir to pass as the hook's TMPDIR env
 */
export function seedSessionLedger(root, sid, paths) {
  const tmp = join(root, '.test-tmpdir');
  mkdirSync(join(tmp, 'devkit-session-edits'), { recursive: true });
  if (paths !== null) {
    writeFileSync(
      join(tmp, 'devkit-session-edits', `${repoKey(root)}-${sid}`),
      `${paths.join('\n')}\n`,
    );
  }
  return tmp;
}

/** REPO_KEY exactly as session-edits-lib.sh computes it (`pwd -P | cksum`, first field). */
export const repoKey = (root) =>
  testSpawnSync('bash', ['-c', 'pwd -P | cksum | cut -d" " -f1'], {
    cwd: root,
    encoding: 'utf8',
  }).stdout.trim();

/**
 * Fixtures for the structure-baseline suites: a self-cleaning tmp repo + a `write(root, rel, content)`
 * helper that mkdir-ps the parent. `const { tmpRepo, write, cleanup } = structFixtures('struct-')`.
 *
 * @param {string} prefix mkdtemp prefix
 */
export function structFixtures(prefix) {
  const { mkTmp, cleanup } = rootRegistry();
  const write = (root, rel, content = 'export {};\n') => {
    mkdirSync(join(root, rel, '..'), { recursive: true });
    writeFileSync(join(root, rel), content);
  };
  return { tmpRepo: () => mkTmp(prefix), write, cleanup };
}

/** sc-2785: labels review's own setup ceiling firing before the wedge marker. Load vs cpus picks the
 *  likelier cause; a reached wedge or a 124 without the banner stays with the strict assertions. */
export function ceilingTimeoutMessage({
  status,
  output,
  marker,
  expected,
  loadavg: load = loadavg(),
  cpus = availableParallelism(),
}: {
  status: number | null;
  output: string;
  marker: string;
  expected: string;
  loadavg?: number[];
  cpus?: number;
}): string | null {
  const banner = SETUP_CEILING_RE.exec(output);
  if (status !== 124 || output.includes(marker) || !banner) return null;
  const [, ceiling, reached] = banner;
  const cause =
    (load[0] ?? 0) > cpus
      ? 'loadavg exceeds the cpu count, so machine load is the likely cause'
      : `loadavg is within the cpu count, so suspect a real hang in ${reached}`;
  return (
    `ceiling-timeout: the ${ceiling}s setup ceiling fired during ${reached} before reaching ` +
    `${expected} (wedge marker ${marker} absent; ${formatLoad(load, cpus)}). ${cause}. ` +
    `Re-run this file alone to tell load from a regression.\n\n${output}`
  );
}

base.cli/__tests__/pre-push.test.mts:
import { execFileSync } from 'node:child_process';
import {
  chmodSync,
  copyFileSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  realpathSync,
  rmSync,
  symlinkSync,
  utimesSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterEach, describe, expect, it } from 'vitest';
import { testSpawnSync } from './_helpers.mts';

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const PRE_PUSH_HOOK = join(REPO_ROOT, '.husky/pre-push');
const ZERO_OID = '0000000000000000000000000000000000000000';
const cleanupPaths: string[] = [];

function git(root: string, ...args: string[]): string {
  return execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
}

function seedRepository(): {
  fakeBin: string;
  logPath: string;
  root: string;
  tagOid: string;
} {
  const root = mkdtempSync(join(tmpdir(), 'devkit-pre-push-'));
  cleanupPaths.push(root);
  git(root, 'init', '-q');
  git(root, 'config', 'user.email', 'pre-push-test@example.com');
  git(root, 'config', 'user.name', 'Pre-push Test');
  git(root, 'config', 'core.hooksPath', '.husky/_');

  mkdirSync(join(root, '.husky/_'), { recursive: true });
  const preCommit = join(root, '.husky/_/pre-commit');
  writeFileSync(preCommit, '#!/bin/sh\nexit 0\n');
  chmodSync(preCommit, 0o755);
  writeFileSync(join(root, 'package.json'), '{"name":"pre-push-fixture","private":true}\n');
  writeFileSync(join(root, 'tracked.mts'), 'export const clean = true;\n');
  for (const relativePath of [
    'cli/lib/husky/pre-push-validation.sh',
    'cli/lib/ship/dependency-preflight.mts',
    'cli/lib/ship/prepare-gate-worktree.sh',
  ]) {
    const destination = join(root, relativePath);
    mkdirSync(dirname(destination), { recursive: true });
    copyFileSync(join(REPO_ROOT, relativePath), destination);
  }
  // Links, not copies: node resolves each module's imports from the real checkout.
  for (const linked of [
    'cli/lib/husky/overlay/overlay-root.mts',
    'cli/lib/husky/pre-push/failing-test-files.mts',
  ]) {
    mkdirSync(dirname(join(root, linked)), { recursive: true });
    symlinkSync(join(REPO_ROOT, linked), join(root, linked));
  }
  git(root, 'add', 'package.json', 'tracked.mts', 'cli');
  git(root, 'commit', '-qm', 'seed');
  git(root, 'tag', '-a', 'v1.0.0', '-m', 'fixture tag');

  mkdirSync(join(root, 'node_modules'), { recursive: true });
  const fakeBin = join(root, 'fake-bin');
  const logPath = join(root, 'bun.log');
  mkdirSync(fakeBin);
  const fakeBun = join(fakeBin, 'bun');
  writeFileSync(
    fakeBun,
    [
      '#!/bin/sh',
      'printf "%s\\t%s\\n" "$PWD" "$*" >> "$PRE_PUSH_TEST_LOG"',
      // A distinctive, non-1 code: the hook must propagate the gate's OWN status, not a normalised 1.
      'case " $* " in *" run typecheck "*) [ ! -e "$PWD/fail-typecheck" ] || exit 7 ;; esac',
      // Fails the SUITE only, so a test can reach the test phase — dirty-only.mts fails both.
      'case " $* " in *" run test:run "*) [ ! -e "$PWD/fail-tests" ] || exit 7 ;; esac',
      '[ ! -e "$PWD/dirty-only.mts" ]',
      '',
    ].join('\n'),
  );
  chmodSync(fakeBun, 0o755);

  return {
    fakeBin,
    logPath,
    root,
    tagOid: git(root, 'rev-parse', 'refs/tags/v1.0.0'),
  };
}

function runPrePush(
  root: string,
  fakeBin: string,
  logPath: string,
  input: string,
  extraEnv: Record<string, string> = {},
) {
  // Supervised: this runs the REAL validation script and its gate-chain process tree. See
  // docs/decisions/suite-hangs-bound-at-the-spawn-site.md (sc-2393).
  return testSpawnSync('sh', ['-e', PRE_PUSH_HOOK, 'origin', 'fixture://origin'], {
    cwd: root,
    encoding: 'utf8',
    env: {
      ...process.env,
      PATH: `${fakeBin}:${process.env.PATH ?? ''}`,
      PRE_PUSH_TEST_LOG: logPath,
      ...extraEnv,
    },
    input,
  });
}

function readLog(logPath: string): string[] {
  return readFileSync(logPath, 'utf8').trim().split('\n');
}

afterEach(() => {
  for (const path of cleanupPaths.splice(0)) {
    rmSync(path, { force: true, recursive: true });
  }
});

describe('devkit repository pre-push hook', () => {
  it('validates an annotated tag in an isolated worktree at the tagged commit', () => {
    const { fakeBin, logPath, root, tagOid } = seedRepository();
    writeFileSync(join(root, 'dirty-only.mts'), 'const unrelatedTypeError: string = 1;\n');

    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/tags/v1.0.0 ${tagOid} refs/tags/v1.0.0 ${ZERO_OID}\n`,
    );

    expect(result.stderr).toContain(`validating tagged commit ${git(root, 'rev-parse', 'HEAD')}`);
    expect(result.stderr).toContain('tag validation: linked node_modules');
    expect(result.status).toBe(0);
    const invocations = readLog(logPath);
    expect(invocations).toHaveLength(2);
    expect(invocations[0]).toContain('\trun typecheck');
    expect(invocations[1]).toContain('\trun test:run');
    for (const invocation of invocations) {
      expect(invocation.startsWith(`${realpathSync(root)}\t`)).toBe(false);
    }
    expect(git(root, 'worktree', 'list', '--porcelain').match(/^worktree /gm)).toHaveLength(1);
  });

  it('keeps branch-push validation in the caller worktree', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const head = git(root, 'rev-parse', 'HEAD');

    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${ZERO_OID}\n`,
    );

    expect(result.stderr).toBe('');
    expect(result.status).toBe(0);
    expect(readLog(logPath)).toEqual([
      `${realpathSync(root)}\trun typecheck`,
      `${realpathSync(root)}\trun test:run`,
    ]);
  });

  it('does not run source validation for a tag deletion', () => {
    const { fakeBin, logPath, root } = seedRepository();

    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `(delete) ${ZERO_OID} refs/tags/v1.0.0 ${git(root, 'rev-parse', 'HEAD')}\n`,
    );

    expect(result.stderr).toBe('');
    expect(result.status).toBe(0);
    expect(() => readFileSync(logPath, 'utf8')).toThrow();
  });

  // sc-1508: a devkit ship hands the hook the exact commit it is pushing. That one commit's suite is
  // gated by CI on the PR, so the local pre-push suite is skipped for it — content-keyed and fail-closed.
  it('skips the pre-push suite for a devkit ship of the exact pushed commit', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const head = git(root, 'rev-parse', 'HEAD');

    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${ZERO_OID}\n`,
      { DEVKIT_SHIP_PREPUSH_SKIP_SHA: head },
    );

    expect(result.status).toBe(0);
    expect(result.stderr).toContain(`${head} is a devkit ship`);
    expect(result.stderr).toContain('skipping the local pre-push suite');
    // The fake bun logs every invocation; a skipped suite never touches it, so the log never exists.
    expect(() => readFileSync(logPath, 'utf8')).toThrow();
  });

  it('runs the full suite when the ship sha does not match the pushed commit (fail-closed)', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const head = git(root, 'rev-parse', 'HEAD');
    const otherSha = 'a'.repeat(40); // valid 40-hex oid, but not the commit being pushed

    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${ZERO_OID}\n`,
      { DEVKIT_SHIP_PREPUSH_SKIP_SHA: otherSha },
    );

    expect(result.status).toBe(0);
    expect(result.stderr).not.toContain('devkit ship');
    expect(readLog(logPath)).toEqual([
      `${realpathSync(root)}\trun typecheck`,
      `${realpathSync(root)}\trun test:run`,
    ]);
  });

  it('ignores a non-oid ship marker and runs the full suite', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const head = git(root, 'rev-parse', 'HEAD');

    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${ZERO_OID}\n`,
      { DEVKIT_SHIP_PREPUSH_SKIP_SHA: 'ship-in-progress' }, // junk → treated as absent
    );

    expect(result.status).toBe(0);
    expect(result.stderr).not.toContain('devkit ship');
    expect(readLog(logPath)).toEqual([
      `${realpathSync(root)}\trun typecheck`,
      `${realpathSync(root)}\trun test:run`,
    ]);
  });

  it('fail-closed on a mixed push where another branch is not the ship commit', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const head = git(root, 'rev-parse', 'HEAD');
    const otherSha = 'b'.repeat(40); // a second branch at a different tip, pushed alongside the ship commit

    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${ZERO_OID}\n` +
        `refs/heads/other ${otherSha} refs/heads/other ${ZERO_OID}\n`,
      { DEVKIT_SHIP_PREPUSH_SKIP_SHA: head },
    );

    expect(result.status).toBe(0);
    expect(result.stderr).not.toContain('devkit ship');
    expect(readLog(logPath)).toEqual([
      `${realpathSync(root)}\trun typecheck`,
      `${realpathSync(root)}\trun test:run`,
    ]);
  });
});

// sc-2198: a blocked push now names its base so a correct block is not read as flake. The block
// itself must be untouched — these assert the verdict, not the narration.
describe('pre-push failure attribution', () => {
  it('preserves the gate’s own exit code, not a normalised 1', () => {
    const { fakeBin, logPath, root } = seedRepository();
    writeFileSync(join(root, 'fail-typecheck'), '');
    const head = git(root, 'rev-parse', 'HEAD');
    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${ZERO_OID}\n`,
    );
    expect(result.status).toBe(7);
  });

  it('says nothing after a TYPECHECK failure — there are no test results to attribute', () => {
    const { fakeBin, logPath, root } = seedRepository();
    writeFileSync(join(root, 'fail-typecheck'), '');
    const head = git(root, 'rev-parse', 'HEAD');
    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${ZERO_OID}\n`,
    );
    expect(result.stderr).not.toContain('push base');
    // Exactly one command ran: the suite is never reached.
    expect(readLog(logPath)).toEqual([`${realpathSync(root)}\trun typecheck`]);
  });

  it('names the base when the suite fails and the base resolves', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const base = git(root, 'rev-parse', 'HEAD');
    writeFileSync(join(root, 'later.mts'), 'export const later = true;\n');
    git(root, 'add', 'later.mts');
    git(root, 'commit', '-qm', 'later');
    const head = git(root, 'rev-parse', 'HEAD');
    writeFileSync(join(root, 'fail-tests'), '');
    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${base}\n`,
    );
    expect(result.status).toBe(7);
    expect(result.stderr).toContain('pre-date your push');
    expect(result.stderr).toContain(base.slice(0, 7));
  });

  it('stays silent on a brand-new branch with no remote knowledge', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const head = git(root, 'rev-parse', 'HEAD');
    writeFileSync(join(root, 'fail-tests'), '');
    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/new ${head} refs/heads/new ${ZERO_OID}\n`,
    );
    expect(result.status).not.toBe(0);
    expect(result.stderr).not.toContain('push base');
    expect(result.stderr).not.toContain('pre-date your push');
  });

  it('stays silent when two refs carry the same tree to different remote tips', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const base = git(root, 'rev-parse', 'HEAD');
    writeFileSync(join(root, 'later.mts'), 'export const later = true;\n');
    git(root, 'add', 'later.mts');
    git(root, 'commit', '-qm', 'later');
    const head = git(root, 'rev-parse', 'HEAD');
    writeFileSync(join(root, 'fail-tests'), '');
    // Which base gets narrated would otherwise be a function of input order alone.
    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${base}\n` +
        `refs/heads/other ${head} refs/heads/other ${head}\n`,
    );
    expect(result.status).toBe(7);
    expect(result.stderr).not.toContain('pre-date your push');
  });

  // run_checks tests the WORKTREE. Pushing a ref that carries some other commit means the tested
  // tree was never that ref's, so naming its base would blame the wrong change entirely.
  it('stays silent when the pushed ref is not the tree that was tested', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const base = git(root, 'rev-parse', 'HEAD');
    // A second branch whose tip is a DIFFERENT commit from the checked-out HEAD.
    git(root, 'checkout', '-q', '-b', 'feature');
    writeFileSync(join(root, 'feature-only.mts'), 'export const f = true;\n');
    git(root, 'add', 'feature-only.mts');
    git(root, 'commit', '-qm', 'feature');
    const featureTip = git(root, 'rev-parse', 'HEAD');
    git(root, 'checkout', '-q', '-');
    const headNow = git(root, 'rev-parse', 'HEAD');
    expect(featureTip).not.toBe(headNow);

    writeFileSync(join(root, 'fail-tests'), '');
    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/feature ${featureTip} refs/heads/feature ${base}\n`,
    );
    expect(result.status).toBe(7);
    expect(result.stderr).not.toContain('pre-date your push');
    expect(result.stderr).not.toContain('in your change');
  });

  it('can be turned off without changing the verdict', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const base = git(root, 'rev-parse', 'HEAD');
    writeFileSync(join(root, 'later.mts'), 'export const later = true;\n');
    git(root, 'add', 'later.mts');
    git(root, 'commit', '-qm', 'later');
    const head = git(root, 'rev-parse', 'HEAD');
    writeFileSync(join(root, 'fail-tests'), '');
    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/heads/main ${head} refs/heads/main ${base}\n`,
      { DEVKIT_PREPUSH_ATTRIBUTION: '0' },
    );
    expect(result.status).not.toBe(0);
    expect(result.stderr).not.toContain('pre-date your push');
  });

  // Git writes an all-zero oid at the repository's HASH WIDTH: 40 for SHA-1, 64 for SHA-256. A
  // fixed-width literal makes every deletion in a SHA-256 repo read as a real update, and the hook
  // then tries to peel a commit from an oid that cannot exist.
  it('treats a 64-zero (SHA-256) oid as a deletion, not a real update', () => {
    const { fakeBin, logPath, root } = seedRepository();
    const sha256Zero = '0'.repeat(64);
    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/tags/v1.0.0 ${sha256Zero} refs/tags/v1.0.0 ${sha256Zero}\n`,
    );
    // A tag deletion has no source tree to validate: exit 0 with the suite never invoked.
    expect(result.status, result.stderr).toBe(0);
    expect(existsSync(logPath)).toBe(false);
  });

  it('emits no attribution on the tag path', () => {
    const { fakeBin, logPath, root, tagOid } = seedRepository();
    writeFileSync(join(root, 'dirty-only.mts'), '');
    git(root, 'add', 'dirty-only.mts');
    git(root, 'commit', '-qm', 'poison');
    git(root, 'tag', '-a', 'v2.0.0', '-m', 'poisoned');
    const poisoned = git(root, 'rev-parse', 'refs/tags/v2.0.0');
    const result = runPrePush(
      root,
      fakeBin,
      logPath,
      `refs/tags/v2.0.0 ${poisoned} refs/tags/v2.0.0 ${ZERO_OID}\n`,
    );
    expect(result.status).not.toBe(0);
    expect(result.stderr).not.toContain('pre-date your push');
    expect(tagOid).toBeTruthy();
  });
});

/** Write a vitest results cache into the fixture, `ageSeconds` old (negative = newer than the push). */
function seedResultsCache(root: string, entries: [string, boolean][], ageSeconds = -60): string {
  const cacheDir = join(root, 'node_modules/.vite/vitest/fixture');
  mkdirSync(cacheDir, { recursive: true });
  const path = join(cacheDir, 'results.json');
  const results = entries.map(([key, failed]) => [key, { duration: 1, failed }]);
  writeFileSync(path, JSON.stringify({ version: 'fixture', results }));
  const stamp = Date.now() / 1000 - ageSeconds;
  utimesSync(path, stamp, stamp);
  return path;
}

/** A fixture whose suite fails, with `a.test.mts` and `b.test.mts` present on disk. */
function seedFailingSuite() {
  const seeded = seedRepository();
  for (const name of ['a.test.mts', 'b.test.mts']) writeFileSync(join(seeded.root, name), '');
  writeFileSync(join(seeded.root, 'fail-tests'), '');
  const head = git(seeded.root, 'rev-parse', 'HEAD');
  const branch = git(seeded.root, 'symbolic-ref', '--short', 'HEAD');
  return {
    ...seeded,
    input: `refs/heads/${branch} ${head} refs/heads/${branch} ${ZERO_OID}\n`,
    log: join(seeded.root, `.devkit/last-pre-push-${branch}.log`),
  };
}

describe('pre-push failing-file list', () => {
  it('persists the failing files and names them and the log as its last lines', () => {
    const { fakeBin, input, log, logPath, root } = seedFailingSuite();
    seedResultsCache(root, [
      ['parallel:b.test.mts', true],
      ['parallel:a.test.mts', true],
      ['git-integration:a.test.mts', true],
      ['parallel:tracked.mts', false],
    ]);
    const result = runPrePush(root, fakeBin, logPath, input);

    expect(result.status).toBe(7);
    expect(result.stderr.trimEnd().split('\n').slice(-4)).toEqual([
      "Failing test files (per vitest's results cache):",
      '  a.test.mts',
      '  b.test.mts',
      `Full list: ${realpathSync(log)}`,
    ]);
    const persisted = readFileSync(log, 'utf8');
    expect(persisted).toContain(`(exit 7) at ${git(root, 'rev-parse', 'HEAD')}`);
    expect(persisted.trimEnd().split('\n').slice(-2)).toEqual(['a.test.mts', 'b.test.mts']);
  });

  it('ignores entries this suite cannot have written: an unnamed project or a deleted file', () => {
    const { fakeBin, input, log, logPath, root } = seedFailingSuite();
    seedResultsCache(root, [
      [':b.test.mts', true],
      ['parallel:gone.test.mts', true],
      ['parallel:a.test.mts', true],
    ]);
    const result = runPrePush(root, fakeBin, logPath, input);

    expect(result.stderr).toContain('  a.test.mts');
    expect(result.stderr).not.toContain('b.test.mts');
    expect(readFileSync(log, 'utf8')).not.toContain('gone.test.mts');
  });

  it('says nothing from a cache older than the push, and drops the previous attempt’s log', () => {
    const { fakeBin, input, log, logPath, root } = seedFailingSuite();
    seedResultsCache(root, [['parallel:a.test.mts', true]], 3600);
    mkdirSync(dirname(log), { recursive: true });
    writeFileSync(log, 'an earlier attempt\n');
    const result = runPrePush(root, fakeBin, logPath, input);

    expect(result.status).toBe(7);
    expect(result.stderr).not.toContain('Failing test files');
    expect(existsSync(log)).toBe(false);
  });

  it('says nothing when the cache is unreadable', () => {
    const { fakeBin, input, log, logPath, root } = seedFailingSuite();
    const cache = seedResultsCache(root, []);
    writeFileSync(cache, '{"results":[["parallel:a.test.mts",{"fai');
    const result = runPrePush(root, fakeBin, logPath, input);

    expect(result.status).toBe(7);
    expect(result.stderr).not.toContain('Failing test files');
    expect(existsSync(log)).toBe(false);
  });

  it('says nothing when node_modules is a link to an install other checkouts share', () => {
    const { fakeBin, input, log, logPath, root } = seedFailingSuite();
    seedResultsCache(root, [['parallel:a.test.mts', true]]);
    const shared = join(root, 'shared-install');
    execFileSync('mv', [join(root, 'node_modules'), shared]);
    symlinkSync(shared, join(root, 'node_modules'));
    const result = runPrePush(root, fakeBin, logPath, input);

    expect(result.status).toBe(7);
    expect(result.stderr).not.toContain('Failing test files');
    expect(existsSync(log)).toBe(false);
  });

  it('says nothing after a typecheck failure or when turned off', () => {
    const { fakeBin, input, log, logPath, root } = seedFailingSuite();
    seedResultsCache(root, [['parallel:a.test.mts', true]]);
    const off = runPrePush(root, fakeBin, logPath, input, { DEVKIT_PREPUSH_ATTRIBUTION: '0' });
    // A typecheck block has no list of its own, so an earlier attempt's must not outlive it.
    mkdirSync(dirname(log), { recursive: true });
    writeFileSync(log, 'an earlier attempt\n');
    writeFileSync(join(root, 'fail-typecheck'), '');
    const typecheck = runPrePush(root, fakeBin, logPath, input);

    for (const result of [off, typecheck]) {
      expect(result.status).toBe(7);
      expect(result.stderr).not.toContain('Failing test files');
    }
    expect(existsSync(log)).toBe(false);
  });

  // A file moved between projects keeps its old key forever; which verdict is current is unknowable.
  it('does not name a file whose projects disagree about it', () => {
    const { fakeBin, input, logPath, root } = seedFailingSuite();
    seedResultsCache(root, [
      ['parallel:a.test.mts', true],
      ['git-integration:a.test.mts', false],
      ['parallel:b.test.mts', true],
    ]);
    const result = runPrePush(root, fakeBin, logPath, input);

    expect(result.stderr).toContain('  b.test.mts');
    expect(result.stderr).not.toContain('a.test.mts');
  });

  it('prints at most twenty names and keeps the whole list in the log', () => {
    const { fakeBin, input, log, logPath, root } = seedFailingSuite();
    const names = Array.from({ length: 21 }, (_, i) => `f${String(i).padStart(2, '0')}.test.mts`);
    for (const name of names) writeFileSync(join(root, name), '');
    seedResultsCache(
      root,
      names.map((name) => [`parallel:${name}`, true]),
    );
    const result = runPrePush(root, fakeBin, logPath, input);

    expect(result.status).toBe(7);
    expect(result.stderr).toContain('  f19.test.mts\n  ... and 1 more\nFull list: ');
    expect(result.stderr).not.toContain('f20.test.mts');
    expect(readFileSync(log, 'utf8')).toContain('f20.test.mts');
  });

  it('keeps the verdict and says nothing when the reader cannot run', () => {
    const { fakeBin, input, log, logPath, root } = seedFailingSuite();
    seedResultsCache(root, [['parallel:a.test.mts', true]]);
    rmSync(join(root, 'cli/lib/husky/pre-push/failing-test-files.mts'));
    const result = runPrePush(root, fakeBin, logPath, input);

    expect(result.status).toBe(7);
    expect(result.stderr).toBe('');
    expect(existsSync(log)).toBe(false);
  });

  it('leaves a green push untouched even when the cache holds old failures', () => {
    const { fakeBin, input, log, logPath, root } = seedFailingSuite();
    rmSync(join(root, 'fail-tests'));
    seedResultsCache(root, [['parallel:a.test.mts', true]]);
    const result = runPrePush(root, fakeBin, logPath, input);

    expect(result.status, result.stderr).toBe(0);
    expect(result.stderr).toBe('');
    expect(existsSync(log)).toBe(false);
    expect(readLog(logPath)).toHaveLength(2);
  });

  it('names the log after a slashed branch, or the short sha on a detached HEAD', () => {
    const { fakeBin, logPath, root } = seedFailingSuite();
    seedResultsCache(root, [['parallel:a.test.mts', true]]);
    const head = git(root, 'rev-parse', 'HEAD');
    const input = `refs/heads/x ${head} refs/heads/x ${ZERO_OID}\n`;
    git(root, 'checkout', '-q', '-b', 'team/topic');
    runPrePush(root, fakeBin, logPath, input);
    git(root, 'checkout', '-q', '--detach');
    runPrePush(root, fakeBin, logPath, input);

    expect(existsSync(join(root, '.devkit/last-pre-push-team-topic.log'))).toBe(true);
    const short = git(root, 'rev-parse', '--short', 'HEAD');
    expect(existsSync(join(root, `.devkit/last-pre-push-${short}.log`))).toBe(true);
  });
});

