/**
 * The PRODUCER side of the coverage gate — `devkit coverage-run`.
 *
 * gate-engine/coverage/run.mts reads `coverage/coverage-final.json`; this module is what puts a
 * trustworthy one there when several agents share one working tree, which is devkit's stated premise
 * (cli/lib/ship/ship-branch.sh: "parallel agents share one working tree").
 *
 * WHY it exists (sc-1214): vitest derives its coverage temp dir as `resolve(reportsDirectory, '.tmp')`
 * and deletes it TWICE per run — `clean()` at startup takes the whole reportsDirectory (`clean: true`
 * is the default), and `cleanAfterRun()` takes `.tmp` again at the end. With the conventional
 * `reportsDirectory: './coverage'`, two runs in one checkout share one `.tmp` and either sweep can
 * land inside the other's lifetime. Reproduced: the run that dies is the one that started SECOND,
 * killed by the first one FINISHING, with "Something removed the coverage directory ... Vitest
 * created earlier" and an ENOENT unhandled rejection. A consumer that selected the fail-CLOSED
 * coverage gate then cannot satisfy it at all while a sibling agent is testing.
 *
 * The fix needs NO change to the consumer's vitest config: `--coverage.reportsDirectory=<dir>` on the
 * command line overrides whatever the config file says, so each run gets `coverage/.runs/<unique>`
 * and republishes to the stable path afterwards. That keeps this a devkit-owned fix rather than one
 * every consumer has to re-implement.
 *
 * Run dirs live under `coverage/` (not os.tmpdir()) so publishing is a same-filesystem rename — atomic,
 * so a reader never sees a torn report — and so the consumer's existing `coverage` gitignore entry
 * already covers them.
 *
 * Vitest-only ON PURPOSE. The gate itself is runner-agnostic (it reads an istanbul-shaped JSON, which
 * jest/c8/nyc also emit), so this refuses loudly rather than guessing when vitest is absent.
 */
import {
  type Dirent,
  existsSync,
  mkdirSync,
  readdirSync,
  renameSync,
  rmSync,
  statSync,
} from 'node:fs';
import { basename, join } from 'node:path';
import { emitGateEvent } from '../judge/gate-events.mts';
import {
  formatDiagnosis,
  formatRerunNotice,
  formatRerunRescue,
  headSha,
  markerCause,
  raisedTimeoutMs,
  readClearMarker,
  readDiagnosis,
  removeClearMarker,
  RESULTS_NAME,
  RETRY_CONDITION,
  type RunDiagnosis,
  stagedFiles,
  UNHANDLED_REPORTER,
  writeClearMarker,
} from './failures.mts';
import {
  ownsReporter,
  ownsRetry,
  ownsTimeoutBudget,
  resolveVitest,
  runVitestDetailed,
  type VitestRun,
} from './vitest-cli.mts';
import {
  detectVitestVersion,
  RETRY_MIN_VITEST,
  supportsRetryCondition,
} from './vitest-version.mts';
import {
  markTouchedDuringRun,
  publishManifest,
  type SourceSnapshot,
  snapshotSource,
  stageManifest,
} from './provenance.mts';

export const COVERAGE_DIR = 'coverage';
export const REPORT_NAME = 'coverage-final.json';
/** The artifact path the coverage GATE reads. Single source of truth for both sides. */
export const COVERAGE_FILE = `${COVERAGE_DIR}/${REPORT_NAME}`;
export const RUNS_DIR = `${COVERAGE_DIR}/.runs`;
/** Long enough it can never catch a live run; short enough that killed runs don't pile up. */
export const STALE_RUN_MS = 6 * 60 * 60 * 1000;

/**
 * What publishCoverage did. `kept` = a sibling's report survived us; `cleared` = ours was removed.
 * Distinct on purpose — see the doc on publishCoverage.
 */
export type PublishOutcome = 'published' | 'cleared' | 'kept';

/**
 * This run's reports directory, absolute. pid alone is not enough — pids are recycled and two runs
 * can start in the same millisecond — hence the random suffix.
 */
export function resolveRunDir(cwd: string, pid = process.pid, now = Date.now()): string {
  return join(cwd, RUNS_DIR, `${pid}-${now}-${Math.random().toString(36).slice(2, 8)}`);
}

/**
 * Drop run directories left behind by killed runs. Best-effort: a live sibling may delete a directory
 * between our readdir and our stat, and losing that race is not a reason to fail somebody's tests.
 */
export function pruneStaleRuns(cwd: string, now = Date.now(), maxAgeMs = STALE_RUN_MS): number {
  let entries: Dirent[];
  try {
    entries = readdirSync(join(cwd, RUNS_DIR), { withFileTypes: true });
  } catch {
    return 0; // no .runs/ yet
  }
  let pruned = 0;
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const dir = join(cwd, RUNS_DIR, entry.name);
    try {
      if (now - statSync(dir).mtimeMs < maxAgeMs) continue;
      rmSync(dir, { recursive: true, force: true });
      pruned++;
    } catch {
      // raced with a sibling, or not ours to remove
    }
  }
  return pruned;
}

/** The stable artifact's mtime, or null when there is none. Snapshot this BEFORE the run starts. */
export function snapshotArtifact(cwd: string): number | null {
  try {
    return statSync(join(cwd, COVERAGE_FILE)).mtimeMs;
  } catch {
    return null;
  }
}

/**
 * Move this run's report to the stable path — the step that keeps the gate honest.
 *
 * Returns WHICH of the three things happened. `cleared` and `kept` are both "no report published",
 * but they are opposite facts about the artifact — one was destroyed by us, one was a sibling's and
 * survived — and only `cleared` may leave a marker saying so (sc-2298). Collapsing them, as the old
 * boolean did, is what would make that marker lie on the non-interference path.
 *
 * When the run produced NO report (tests failed; vitest's `reportOnFailure` is false by default, so
 * nothing is written) it removes the stale artifact rather than leaving the previous run's behind —
 * UNLESS a sibling replaced it while we were running.
 *
 * Two properties have to hold at once, and `before` (from snapshotArtifact, taken before the run)
 * is what reconciles them:
 *
 *  - FAIL-CLOSED. While reportsDirectory was `./coverage`, vitest's startup `rm -rf` had already
 *    wiped the old report, so a failed run left no artifact and the gate blocked — the behaviour
 *    docs/decisions/coverage-gate.md exists to protect. Publishing per-run without any clear would
 *    silently convert that gate to fail-OPEN.
 *  - NO CROSS-RUN DESTRUCTION. An artifact that CHANGED during our run belongs to a sibling that
 *    succeeded while we were going. Deleting it would let a failing run destroy a passing run's
 *    result — reintroducing, at the artifact level, the interference this module exists to remove.
 *
 * IDENTITY, NOT WALL-CLOCK. An earlier cut compared the artifact's mtime against the run's start
 * time, which is unsound: `Date.now()` is millisecond-truncated while mtimes carry sub-millisecond
 * precision, so an artifact written in the SAME millisecond the run started reads as "newer" and
 * survives — a fail-open whose likelihood depends on how fast the machine is. Comparing the mtime to
 * the one observed before the run is exact: unchanged means it is the very file we started with.
 *
 * CLAIM FIRST, INSPECT SECOND. `stat` then `unlink` would be a TOCTOU: a sibling can publish in the
 * gap and we would delete the good report it just wrote. `rename` is atomic, so the claim has exactly
 * one winner and nothing arriving afterwards can be destroyed by us.
 */
export function publishCoverage(
  runDir: string,
  cwd: string,
  before: number | null,
  diagnosis: RunDiagnosis | null = null,
  source: SourceSnapshot | null = null,
): PublishOutcome {
  const fresh = join(runDir, REPORT_NAME);
  const stable = join(cwd, COVERAGE_FILE);
  const coverageDir = join(cwd, COVERAGE_DIR);
  if (existsSync(fresh)) {
    mkdirSync(coverageDir, { recursive: true });
    // Staged from OUR report before it moves, so its hash matches only this run's file (sc-3225).
    // No snapshot → no manifest; a previous one mismatches this artifact's hash and reads as unknown.
    let manifest: string | null = null;
    try {
      manifest = source ? stageManifest(runDir, fresh, source, basename(runDir)) : null;
    } catch {
      manifest = null;
    }
    renameSync(fresh, stable);
    if (manifest) publishManifest(manifest, coverageDir);
    // A fresh report answers every question the marker existed to answer; leaving it would let the
    // gate narrate an old failure over a current pass.
    removeClearMarker(coverageDir);
    return 'published';
  }
  // The claim target sits BESIDE `stable` in coverage/, never inside runDir. vitest's
  // `cleanAfterRun()` removes the reports directory whenever it ends up empty — precisely what a
  // failed run leaves behind, the case this clear exists for. Renaming into a directory vitest just
  // deleted throws ENOENT, the catch swallows it, and the stale artifact survives. Beside it, the
  // directory is guaranteed to exist (it holds `stable`) and stays on one filesystem, so the rename
  // is still atomic.
  const claimed = join(cwd, COVERAGE_DIR, `.cleared-${basename(runDir)}-${REPORT_NAME}`);
  try {
    renameSync(stable, claimed);
  } catch {
    return 'kept'; // nothing to clear, or a sibling claimed it first
  }
  try {
    // Appeared from nothing, or changed under us ⇒ a sibling's successful report ⇒ put it back.
    if (before === null || statSync(claimed).mtimeMs !== before) {
      renameSync(claimed, stable);
      return 'kept';
    }
  } catch {
    // Unreadable/unrestorable — fall through and drop it; an artifact we cannot vouch for must not
    // be left where the gate would trust it.
  }
  // BEFORE the removal, and only on this branch. 'kept' means a sibling's good report survived, so a
  // marker there would tell the next reader an artifact was discarded when one was deliberately
  // preserved — a lie about the exact non-interference property sc-1214 spent three cuts securing.
  // Writing it first also means the artifact can never be gone with nothing explaining why.
  writeClearMarker(coverageDir, {
    clearedAt: new Date().toISOString(),
    previousMtime: before,
    head: headSha(cwd),
    ...markerCause(diagnosis),
  });
  rmSync(claimed, { force: true });
  return 'cleared';
}

/** The flag this runner owns — passing it too is what isolation MEANS, so it cannot be delegated. */
export const RESERVED_FLAG = '--coverage.reportsDirectory';

/** True when the forwarded args try to set the one option this runner must control. */
export function reservesCoverageDir(argv: string[]): boolean {
  return argv.some((arg) => arg === RESERVED_FLAG || arg.startsWith(`${RESERVED_FLAG}=`));
}

/** Set to keep a timeout-only failure as a failure instead of re-running the suite once. */
export const NO_RERUN_ENV = 'DEVKIT_COVERAGE_NO_RERUN';

/** Everything shouldRerun decides from. Pure, so every refusal is testable without a suite. */
export interface RerunInput {
  code: number;
  interrupted: boolean;
  retrying: boolean;
  diagnosis: RunDiagnosis | null;
  argv: string[];
  env: NodeJS.ProcessEnv;
}

/** Whether a failed run is the load flake one WHOLE re-run at a raised budget can rescue (sc-3473;
 * the reasoning, and why each refusal exists, is in the coverage-gate decision). */
export function shouldRerun(input: RerunInput): boolean {
  const { code, interrupted, retrying, diagnosis, argv, env } = input;
  if (code === 0 || interrupted || !retrying) return false;
  if (!diagnosis?.failures?.allTimedOut) return false;
  if (ownsRetry(argv) || ownsTimeoutBudget(argv)) return false;
  return env[NO_RERUN_ENV] !== '1';
}

/** Set to skip the json reporter (and therefore all post-run diagnosis) without touching retry. */
export const NO_DIAGNOSIS_ENV = 'DEVKIT_COVERAGE_NO_DIAGNOSIS';

export function buildInjectedArgs(
  vitest: string,
  argv: string[],
  resultsFile: string,
  cwd: string,
): string[] {
  const injected: string[] = [];
  if (!ownsRetry(argv)) {
    const detected = detectVitestVersion(cwd, vitest);
    if (supportsRetryCondition(detected.kind === 'known' ? detected.majorMinor : null)) {
      injected.push('--retry.count=1', `--retry.condition=${RETRY_CONDITION}`);
    } else {
      // Two different claims, kept apart: "too old" must be checkable, and "could not tell" must not
      // masquerade as "too old" (sc-3731) — both still inject nothing, see supportsRetryCondition.
      console.error(
        detected.kind === 'known'
          ? `ℹ️  Skipping the flake retry: detected vitest ${detected.version}, but --retry.condition needs >=${RETRY_MIN_VITEST.join('.')}.0-beta.1.`
          : `ℹ️  Skipping the flake retry: could not determine the vitest version (${detected.reason}).`,
      );
      console.error('   A timeout-shaped flake will discard the coverage artifact as before.');
    }
  }
  if (!ownsReporter(argv) && !process.env[NO_DIAGNOSIS_ENV]) {
    // `default` is kept so console output is byte-for-byte what the consumer already sees; the json
    // reporter is additive and writes only into our run directory; ours names unhandled errors beside it.
    injected.push(
      '--reporter=default',
      '--reporter=json',
      `--outputFile.json=${resultsFile}`,
      `--reporter=${UNHANDLED_REPORTER}`,
    );
  }
  return injected;
}

/**
 * Say what happened, on stderr, and make the flaky rate measurable.
 *
 * `retrying` is the whole reason this takes the outcome rather than predicting it. Whether devkit's
 * json reporter actually ran cannot be decided from argv: a consumer who sets `reporters` in their
 * vitest.config — which is where reporters are normally set — silently WINS over the CLI flag, so the
 * report never appears while the injected retry still fires. Verified against vitest 4.1.10. Deciding
 * from the artifact covers that, an older vitest ignoring the dotted --outputFile.json, an argv
 * --reporter, and the env switch, with one rule instead of four guesses.
 *
 * A retry nobody can see is the silent relaxation of a pass/fail contract that
 * gate-opt-out-is-visible-and-detectable rules out, so it is disclosed rather than assumed harmless.
 */
export function reportDiagnosis(
  diagnosis: RunDiagnosis | null,
  cwd: string,
  retrying: boolean,
): void {
  if (!diagnosis) {
    if (retrying) {
      console.error(
        '\u2139\uFE0F  Retrying timed-out tests, but the rescue cannot be reported: no devkit json',
      );
      console.error('   report was produced (your vitest.config sets `reporters`, you passed');
      console.error(
        `   --reporter, or ${NO_DIAGNOSIS_ENV} is set). A test that only passes on the`,
      );
      console.error(
        '   retry will look plainly green. Use --retry=0 to turn the retry off instead.',
      );
    }
    return;
  }
  for (const line of formatDiagnosis(diagnosis, cwd, stagedFiles(cwd))) console.error(line);
  if (diagnosis.flaky.length > 0) {
    // Its OWN type, not a `status` on gate_result: docs/decisions/gate-telemetry-self-describing.md
    // Ruling (3). A status the collector does not know settles a run as CLEAN and inflates
    // gate_result's fail-rate denominator — the reasoning sc-1366 used for gate_infra_failure.
    // A rescued flake is not a gate verdict at all: this is the producer, and the run exited 0.
    emitGateEvent({
      type: 'test_flaky',
      gate: 'coverage-run',
      flaky_count: diagnosis.flaky.length,
      detail: `${diagnosis.flaky.length} test(s) passed only on retry`,
    });
  }
}

/** One complete vitest run, settled: published or cleared, run directory gone. */
interface Pass extends VitestRun {
  outcome: PublishOutcome;
  diagnosis: RunDiagnosis | null;
  retrying: boolean;
}

/** One full, isolated coverage run. All per-run state is made fresh here, so a second pass can never
 * read or clear on the strength of the first one's. */
async function runPass(
  vitest: string,
  cwd: string,
  argv: string[],
  budget: string[],
): Promise<Pass> {
  pruneStaleRuns(cwd);
  const runDir = resolveRunDir(cwd);
  mkdirSync(runDir, { recursive: true });
  // Captured BEFORE vitest starts: if the artifact changes from this, a sibling published it while
  // we were running and a failure of ours must not delete it. See publishCoverage.
  const before = snapshotArtifact(cwd);
  // Also BEFORE vitest (sc-3225); anything whose mtime moves during the run is marked unmeasured
  // after it, which catches an edit-then-restore the start hashes alone cannot see.
  const startedAt = Date.now();
  const source = snapshotSource(cwd, argv);

  // Inside runDir, which only this run may touch; results.json also keeps it non-empty, so vitest's
  // cleanAfterRun() has nothing to sweep (the v0.43.1 fail-open).
  const resultsFile = join(runDir, RESULTS_NAME);
  const injected = buildInjectedArgs(vitest, argv, resultsFile, cwd);
  const retrying = injected.some((arg) => arg.startsWith('--retry.'));

  let run: VitestRun = { code: 1, interrupted: false };
  let outcome: PublishOutcome = 'kept';
  let diagnosis: RunDiagnosis | null = null;
  // `finally` so a throw never strands runDir. The diagnosis is read before it goes, and never
  // changes whether the run publishes or clears.
  try {
    // The CLI flag beats the consumer's vitest.config reportsDirectory — no config edit downstream.
    run = await runVitestDetailed(
      vitest,
      [
        'run',
        '--coverage',
        `--coverage.reportsDirectory=${runDir}`,
        ...injected,
        ...budget,
        ...argv,
      ],
      cwd,
    );
    diagnosis = readDiagnosis(resultsFile, run.interrupted ? 0 : run.code);
    // A failed run's report (the consumer's `coverage.reportOnFailure`) is partial: never publish it.
    if (run.code !== 0) rmSync(join(runDir, REPORT_NAME), { force: true });
    const measured =
      source && markTouchedDuringRun(cwd, source, startedAt, join(runDir, REPORT_NAME));
    outcome = publishCoverage(runDir, cwd, before, diagnosis, measured);
  } finally {
    rmSync(runDir, { recursive: true, force: true });
  }
  return { ...run, outcome, diagnosis, retrying };
}

/** Pass 2 was green: say which pass-1 failures only a bigger budget got through, and count them. */
function reportRerunRescue(first: RunDiagnosis | null, cwd: string, budget: number): void {
  const lines = formatRerunRescue(first, cwd, budget);
  for (const line of lines) console.error(line);
  const count = first?.failures?.tests.length || first?.failedFiles.length || 0;
  if (count === 0) return;
  // The same self-describing type a retry rescue uses: this is a flake, not a gate verdict.
  emitGateEvent({
    type: 'test_flaky',
    gate: 'coverage-run',
    flaky_count: count,
    detail: `${count} test(s) passed only on the raised-timeout re-run`,
  });
}

/** Keep the marker's clearedAt (when the artifact went) but name the failures that ended the run. */
function refreshClearMarker(cwd: string, diagnosis: RunDiagnosis | null): void {
  const coverageDir = join(cwd, COVERAGE_DIR);
  if (existsSync(join(cwd, COVERAGE_FILE))) return; // a sibling published in between — not ours
  const marker = readClearMarker(coverageDir);
  if (marker) writeClearMarker(coverageDir, { ...marker, ...markerCause(diagnosis) });
}

/**
 * Run the consumer's vitest suite with coverage in an isolated reports directory, publish the report,
 * and return vitest's exit code.
 */
export async function produceCoverage(cwd = process.cwd(), argv: string[] = []): Promise<number> {
  const vitest = resolveVitest(cwd);
  if (!vitest) {
    console.error('🚫 devkit coverage-run needs vitest — node_modules/.bin/vitest not found.');
    console.error(`   This runner is vitest-only. The coverage GATE is not: it reads any`);
    console.error(`   istanbul-shaped ${COVERAGE_FILE}, so produce one with your own runner`);
    console.error('   and keep using `guard-coverage` as normal.');
    return 1;
  }

  // Passing this through would collide with the flag we add below. vitest rejects the duplicate
  // itself, but with a raw stack trace that names our internal run directory — useless to whoever
  // typed it. Say what is actually wrong instead.
  if (reservesCoverageDir(argv)) {
    console.error(`🚫 ${RESERVED_FLAG} is owned by \`devkit coverage-run\`.`);
    console.error(
      '   Giving every run its own reports directory IS this command; pointing it back',
    );
    console.error(
      `   at a shared one restores the race. The report is published to ${COVERAGE_FILE}`,
    );
    console.error('   regardless — drop the flag and read it there.');
    return 1;
  }

  const first = await runPass(vitest, cwd, argv, []);
  reportDiagnosis(first.diagnosis, cwd, first.retrying && !first.interrupted);
  let final = first;

  if (shouldRerun({ ...first, argv, env: process.env })) {
    // Pass 1 has fully settled — artifact cleared, marker written — before pass 2 starts, so a kill
    // anywhere in pass 2 still leaves the gate failing CLOSED with the reason on disk.
    const budget = raisedTimeoutMs(first.diagnosis?.failures);
    for (const line of formatRerunNotice(budget)) console.error(line);
    final = await runPass(vitest, cwd, argv, [
      `--testTimeout=${budget}`,
      `--hookTimeout=${budget}`,
    ]);
    reportDiagnosis(final.diagnosis, cwd, final.retrying && !final.interrupted);
    if (final.code === 0) {
      reportRerunRescue(first.diagnosis, cwd, budget);
    } else if (first.outcome === 'cleared' && final.outcome === 'kept') {
      // Pass 2 found nothing left to clear because pass 1 already had. The marker still names pass
      // 1's failures; the run that actually ended was pass 2.
      refreshClearMarker(cwd, final.diagnosis);
    }
  }
  const { code, outcome } = final;

  // Green tests but no report means the suite never emitted one — most often because `json` is
  // missing from coverage.reporter. The gate still fails CLOSED on the absent artifact, so this is
  // not a correctness hole; it is a diagnosis. Reporting success here sends the developer to a
  // commit-time block whose cause is three steps upstream, so name it at the point it happened.
  if (code === 0 && outcome !== 'published') {
    console.error(`🚫 vitest passed but produced no ${REPORT_NAME}.`);
    console.error("   The coverage gate reads that file — add 'json' to coverage.reporter in your");
    console.error('   vitest config, then re-run. Exiting non-zero so a run that verified nothing');
    console.error('   is not mistaken for a run that verified coverage.');
    return 1;
  }
  return code;
}

base.gate-engine/coverage/provenance.mts:
/** Coverage artifact provenance (sc-3225): which tree did coverage-final.json measure? Rationale:
 * docs/decisions/coverage-gate.md, the 2026-09-27 sc-3225 notes. */
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  type BigIntStats,
  closeSync,
  existsSync,
  fstatSync,
  lstatSync,
  openSync,
  readFileSync,
  realpathSync,
  renameSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { join, relative, resolve, sep } from 'node:path';
import { z } from 'zod';
import { commitIndexEnv } from '../ratchets/commit-index.mts';

export const MANIFEST_NAME = 'coverage-manifest.json';
/** A path that existed at HEAD but not in the working tree when the run started. */
export const DELETED = 'deleted';
/** A path written while the run was in flight: what it measured is unknowable, so nothing matches. */
export const TOUCHED = 'touched-during-run';

/** What the working tree looked like when a coverage run started. Paths are repo-root relative. */
export interface SourceSnapshot {
  /** Top level as git resolves it AND as the run's cwd spelled it: istanbul keys keep a symlinked
   * prefix (/var vs /private/var) that --show-toplevel resolves away. */
  roots: string[];
  head: string;
  dirty: Record<string, string>;
  /** The vitest args `devkit coverage-run` forwarded; absent in manifests older than the field. */
  args?: string[];
}

export interface CoverageManifest extends SourceSnapshot {
  runId: string;
  finishedAt: string;
  /** sha256 of the coverage-final.json this manifest describes — the manifest↔artifact binding. */
  artifactSha256: string;
  /** dev:ino:mtimeNs of the report file; rename keeps it, any rewrite or replacement changes it. */
  artifactIdentity: string;
}

/** The artifact bytes and the identity of the one file they were read from. */
export interface ArtifactRead {
  bytes: string;
  identity: string;
}

// The manifest is JSON this module wrote, but read back from a directory any tool may touch; parse it
// at the boundary so a hand-edited or foreign file reads as "no manifest", never as a partial one.
const manifestSchema = z.object({
  runId: z.string(),
  finishedAt: z.string(),
  roots: z.array(z.string()),
  head: z.string(),
  dirty: z.record(z.string(), z.string()),
  artifactSha256: z.string(),
  artifactIdentity: z.string(),
  args: z.array(z.string()).optional(),
}) satisfies z.ZodType<CoverageManifest>;

// Only the keys matter here; computePercentages has already validated each entry's shape.
export const artifactKeysSchema = z.record(z.string(), z.unknown());

export type PathKind = 'production' | 'test' | 'other';
/** Classify a briefed repo-relative path; `measured` = the artifact carries an entry for it. */
export type Classify = (path: string, measured: boolean) => PathKind;

export type Provenance =
  | { state: 'unknown'; reason: string }
  | { state: 'fresh'; manifest: CoverageManifest }
  | { state: 'drift'; manifest: CoverageManifest; production: string[]; tests: string[] };

// The commit's own index, not the default one: a pathspec or `-a` commit stages into a temp index.
export const git = (cwd: string, args: string[], input?: string): string =>
  execFileSync('git', ['--literal-pathspecs', ...args], {
    cwd,
    env: commitIndexEnv(cwd),
    encoding: 'utf8',
    input,
    maxBuffer: 256 * 1024 * 1024,
    stdio: ['pipe', 'pipe', 'ignore'],
  });

const nulList = (out: string): string[] => out.split('\0').filter(Boolean);

export const sha256 = (bytes: string | Buffer): string =>
  createHash('sha256').update(bytes).digest('hex');

/** git's top level, plus the same directory as `cwd` spells it when a symlink sits in the prefix. */
export function checkoutRoots(cwd: string, top: string): string[] {
  const logical = resolve(cwd);
  let sub = '';
  try {
    sub = relative(top, realpathSync(logical));
  } catch {
    return [top];
  }
  const suffix = sub ? `${sep}${sub}` : '';
  const spelled = suffix && logical.endsWith(suffix) ? logical.slice(0, -suffix.length) : logical;
  return spelled === top || sub.startsWith('..') ? [top] : [top, spelled];
}

/** HEAD plus a blob id per path that differs from it, taken at run START; null when git cannot answer.
 * `--stdin-paths` applies `git add`'s clean filters, so ids compare directly with tree entries. */
export function snapshotSource(cwd: string, args: string[] = []): SourceSnapshot | null {
  try {
    const top = git(cwd, ['rev-parse', '--show-toplevel']).trim();
    const head = git(top, ['rev-parse', 'HEAD']).trim();
    const changed = new Set([
      ...nulList(git(top, ['diff', '--name-only', '--no-renames', '-z', 'HEAD'])),
      ...nulList(git(top, ['ls-files', '-o', '--exclude-standard', '-z'])),
    ]);
    const dirty: Record<string, string> = {};
    const toHash: string[] = [];
    for (const p of changed) {
      const abs = join(top, p);
      if (!existsSync(abs)) {
        dirty[p] = DELETED;
        continue;
      }
      // A symlink's blob is its link text, which hashing the path would not produce. Leaving it out
      // falls back to HEAD's entry, so a changed link surfaces as drift rather than a false fresh.
      if (lstatSync(abs).isSymbolicLink()) continue;
      toHash.push(p);
    }
    // --stdin-paths is newline-delimited; a path containing one is hashed on its own.
    const plain = toHash.filter((p) => !p.includes('\n'));
    const blobs = plain.length
      ? git(top, ['hash-object', '--stdin-paths'], `${plain.join('\n')}\n`)
          .trim()
          .split('\n')
      : [];
    if (blobs.length !== plain.length) return null;
    for (const [i, p] of plain.entries()) {
      const blob = blobs[i];
      if (blob === undefined) return null;
      dirty[p] = blob;
    }
    for (const p of toHash.filter((q) => q.includes('\n'))) {
      dirty[p] = git(top, ['hash-object', '--', p]).trim();
    }
    return { roots: checkoutRoots(cwd, top), head, dirty, args };
  } catch {
    return null;
  }
}

/** The snapshot with every path whose mtime reached the run's start, or that the report measured but
 * no longer exists, marked TOUCHED; null when git or the filesystem cannot answer. */
export function markTouchedDuringRun(
  cwd: string,
  snapshot: SourceSnapshot,
  startedAt: number,
  reportFile: string,
): SourceSnapshot | null {
  try {
    const top = git(cwd, ['rev-parse', '--show-toplevel']).trim();
    const files = nulList(
      git(top, ['ls-files', '-z', '--cached', '--others', '--exclude-standard']),
    );
    const dirty = { ...snapshot.dirty };
    // Whole-second mtime filesystems round down; the start of that second errs toward a re-run.
    const since = Math.floor(startedAt / 1000) * 1000;
    for (const p of files) {
      const abs = join(top, p);
      if (existsSync(abs) && lstatSync(abs).mtimeMs >= since) dirty[p] = TOUCHED;
    }
    // Measured yet gone now: created and removed mid-run, so no mtime is left to see.
    if (existsSync(reportFile)) {
      for (const p of measuredPaths(readFileSync(reportFile, 'utf8'), snapshot.roots)) {
        if (!existsSync(join(top, p))) dirty[p] = TOUCHED;
      }
    }
    return { ...snapshot, dirty };
  } catch {
    return null;
  }
}

const fileIdentity = (st: BigIntStats): string => `${st.dev}:${st.ino}:${st.mtimeNs}`;

/** Read the report through one descriptor, so its bytes and identity describe the same file. */
export function readArtifact(file: string): ArtifactRead {
  const fd = openSync(file, 'r');
  try {
    return {
      identity: fileIdentity(fstatSync(fd, { bigint: true })),
      bytes: readFileSync(fd, 'utf8'),
    };
  } finally {
    closeSync(fd);
  }
}

/** Stage a manifest for this run's own report inside runDir, so a sibling publishing in between
 * leaves a hash mismatch the gate rejects. Returns its path. */
export function stageManifest(
  runDir: string,
  artifact: string,
  snapshot: SourceSnapshot,
  runId: string,
): string {
  const manifest: CoverageManifest = {
    runId,
    finishedAt: new Date().toISOString(),
    roots: snapshot.roots,
    head: snapshot.head,
    dirty: snapshot.dirty,
    artifactSha256: sha256(readFileSync(artifact)),
    artifactIdentity: fileIdentity(statSync(artifact, { bigint: true })),
    args: snapshot.args,
  };
  const staged = join(runDir, MANIFEST_NAME);
  writeFileSync(staged, `${JSON.stringify(manifest)}\n`);
  return staged;
}

/** Move a staged manifest into coverage/. Best-effort, and it never deletes one: whatever stays is
 * bound to its own artifact by hash, so the gate reads a stale manifest as unknown, never fresh. */
export function publishManifest(staged: string, coverageDir: string): void {
  try {
    renameSync(staged, join(coverageDir, MANIFEST_NAME));
  } catch {
    /* no manifest for this run: the gate reports provenance unknown */
  }
}

/** Manifest text as the manifest, or null when it is not the shape we wrote. Never throws. */
export function parseManifest(text: string): CoverageManifest | null {
  try {
    const parsed = manifestSchema.safeParse(JSON.parse(text));
    return parsed.success ? parsed.data : null;
  } catch {
    return null;
  }
}

/** The manifest, or null when absent or not the shape we wrote. Never throws. */
export function readManifest(coverageDir: string): CoverageManifest | null {
  try {
    return parseManifest(readFileSync(join(coverageDir, MANIFEST_NAME), 'utf8'));
  } catch {
    return null;
  }
}

// Flags that narrow which tests run, so the report cannot speak for the whole repo.
const NARROWING = new Set([
  '-t',
  '--testNamePattern',
  '--project',
  '--shard',
  '--changed',
  '--dir',
  '--root',
  '--exclude',
]);

// Non-narrowing flags whose value may follow as a separate token (`--reporter json`).
const VALUED = new Set([
  '--reporter',
  '--outputFile',
  '--maxWorkers',
  '--minWorkers',
  '--pool',
  '--testTimeout',
  '--hookTimeout',
  '--teardownTimeout',
  '--retry',
  '--bail',
  '--config',
  '-c',
  '--environment',
  '--mode',
  '--browser',
  '--maxConcurrency',
  '--slowTestThreshold',
]);
const VALUED_PREFIX = /^--(coverage|outputFile|retry|poolOptions|browser|sequence)\./;
const SILENT_VALUE = new Set(['true', 'false', 'passed-only']);

/** Did these forwarded vitest args narrow the run? Any bare token not known to be a flag's value is a
 * test filter, so an unrecognised `--flag value` errs toward scoped. */
export function isScopedRun(args: readonly string[]): boolean {
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i] ?? '';
    if (!arg.startsWith('-') || NARROWING.has(arg.split('=')[0] ?? '')) return true;
    if (arg.includes('=')) continue;
    const next = args[i + 1] ?? '';
    if (VALUED.has(arg) || VALUED_PREFIX.test(arg)) i += 1;
    else if (arg === '--silent' && SILENT_VALUE.has(next)) i += 1;
  }
  return false;
}

/** The manifest, only when it describes exactly these artifact bytes from this very file. */
export function boundManifest(
  coverageDir: string,
  artifact: ArtifactRead,
): CoverageManifest | null {
  const manifest = readManifest(coverageDir);
  // Hash AND file identity: byte-identical output from another run is a different measurement.
  return manifest &&
    sha256(artifact.bytes) === manifest.artifactSha256 &&
    artifact.identity === manifest.artifactIdentity
    ? manifest
    : null;
}

/** path → blob id for `paths` in `treeish`. A path absent from the tree is absent from the map. */
export function blobsIn(top: string, treeish: string, paths: string[]): Map<string, string> {
  const out = new Map<string, string>();
  if (paths.length === 0) return out;
  for (const entry of nulList(git(top, ['ls-tree', '-r', '-z', treeish, '--', ...paths]))) {
    const tab = entry.indexOf('\t');
    const oid = entry.slice(0, tab).split(' ')[2];
    if (oid) out.set(entry.slice(tab + 1), oid);
  }
  return out;
}

/** repo-relative path → the artifact key measuring it: istanbul keys by the absolute path in the
 * run's checkout, which `roots` records; keys outside every root are dropped. */
export function keysByPath(artifactKeys: string[], roots: string[]): Map<string, string> {
  const prefixes = roots.map((r) => `${r.replaceAll('\\', '/').replace(/\/$/, '')}/`);
  const out = new Map<string, string>();
  for (const key of artifactKeys) {
    const k = key.replaceAll('\\', '/');
    const prefix = prefixes.find((p) => k.startsWith(p));
    if (prefix) out.set(k.slice(prefix.length), key);
  }
  return out;
}

/** The artifact's measured files as repo-relative paths. */
function measuredPaths(artifact: string, roots: string[]): Set<string> {
  const parsed = artifactKeysSchema.safeParse(JSON.parse(artifact));
  return parsed.success ? new Set(keysByPath(Object.keys(parsed.data), roots).keys()) : new Set();
}

/** Compare each briefed blob with the one the manifest says was measured. `artifact` is the exact
 * bytes the verdict came from; `classify` routes a path to production / test / other (never drift). */
export function checkProvenance(
  cwd: string,
  coverageDir: string,
  artifact: ArtifactRead,
  classify: Classify,
): Provenance {
  if (!readManifest(coverageDir)) {
    return { state: 'unknown', reason: 'no manifest — not produced by `devkit coverage-run`' };
  }
  const manifest = boundManifest(coverageDir, artifact);
  if (!manifest) {
    return { state: 'unknown', reason: 'the artifact was replaced after its manifest was written' };
  }
  try {
    const top = git(cwd, ['rev-parse', '--show-toplevel']).trim();
    // The index as it stands when the gate runs, formatter output included: no exemption, no race.
    const now = git(top, ['write-tree']).trim();
    const briefed = nulList(
      git(top, ['diff-tree', '-r', '--name-only', '--no-renames', '-z', 'HEAD', now]),
    );
    const committed = blobsIn(top, now, briefed);
    const atHead = blobsIn(
      top,
      manifest.head,
      briefed.filter((p) => !Object.hasOwn(manifest.dirty, p)),
    );
    const inArtifact = measuredPaths(artifact.bytes, manifest.roots);
    const production: string[] = [];
    const tests: string[] = [];
    for (const p of briefed) {
      const measured = Object.hasOwn(manifest.dirty, p)
        ? manifest.dirty[p]
        : (atHead.get(p) ?? DELETED);
      if (measured === (committed.get(p) ?? DELETED)) continue;
      const kind = classify(p, inArtifact.has(p));
      if (kind === 'production') production.push(p);
      else if (kind === 'test') tests.push(p);
    }
    return production.length || tests.length
      ? { state: 'drift', manifest, production, tests }
      : { state: 'fresh', manifest };
  } catch {
    return { state: 'unknown', reason: 'git could not compare the briefed files' };
  }
}

// Names the unhandled errors vitest's frozen json reporter omits (vitest-dev/vitest#8669).
// Never throws: it runs inside the consumer's vitest.
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import type { Reporter, SerializedError, TestModule, Vitest } from 'vitest/node';

/** Written beside the json report, in the run directory only this run may touch. */
export const UNHANDLED_NAME = 'unhandled.json';

/** vitest's worker stamps the originating test file onto every unhandled error. */
type ReportedError = SerializedError & { VITEST_TEST_PATH?: string };

export default class UnhandledReporter implements Reporter {
  private out: string | null = null;

  onInit(vitest: Vitest): void {
    try {
      const { outputFile } = vitest.config;
      const json = outputFile instanceof Object ? outputFile.json : undefined;
      if (json) this.out = join(dirname(json), UNHANDLED_NAME);
    } catch {
      this.out = null;
    }
  }

  onTestRunEnd(_modules: ReadonlyArray<TestModule>, errors: ReadonlyArray<ReportedError>): void {
    if (!this.out || errors.length === 0) return;
    try {
      const entries = errors.map((e) => ({
        file: e.VITEST_TEST_PATH ?? null,
        message: `${e.name ?? 'Error'}: ${e.message ?? ''}`.split('\n')[0],
      }));
      writeFileSync(this.out, JSON.stringify(entries));
    } catch {
      /* diagnosis is a courtesy, not a guarantee */
    }
  }
}

base.gate-engine/decisions/cli.mts:
#!/usr/bin/env node

/**
 * guard-decisions — unified CLI for the decision-log engine.
 *
 * Dispatches to the three sub-engines, all of which resolve their paths/knobs from
 * resolveGuardConfig(process.cwd()) — i.e. against the CONSUMER repo, never the package dir (W-3):
 *
 *   guard-decisions add <slug> --target …| --note …   record a Target / append a note
 *   guard-decisions amend <slug> --target …| --note …| --note-replace OLD NEW  correct a draft entry
 *     (--target reaches the newest draft Target even when draft notes follow it)
 *   guard-decisions rescope <slug> --scope … --reason …  append-only Scope correction (a tagged note)
 *   guard-decisions query "<text>" [--top K] [--json|--full]  rank axes (semantic → lexical floor)
 *   guard-decisions reindex | list | show <slug> | check <slug>
 *   guard-decisions detect --gate | scan [--working]  architectural-smell gate (capture B)
 *   guard-decisions check-alignment --gate | scan     scope-matched alignment + depth gate (capture C)
 *   guard-decisions scoped-targets --files <a,b> [--query "<text>" --top K]   governing Targets → JSON
 *   guard-decisions categories                        per-category view (recall/category-report.mts)
 *   guard-decisions enforce [link <slug> --check …]   Checks linked to Targets (ruling-checks/)
 *   guard-decisions integrity [--staged]              structural-integrity scan (integrity/scan.mts);
 *                                                     --staged judges only the records THIS commit
 *                                                     touches, against HEAD (integrity/staged-gate.mts)
 *
 * `detect`, `check-alignment` and `scoped-targets` are called through their exported `main(argv)`
 * (never their run-as-main guard, which an already-loaded module skips); `categories`
 * and `integrity` are plain function calls (neither has a --gate/scan sub-dispatch of its own);
 * everything else routes to decisions.mjs `main`.
 *
 * `integrity` is dispatched HERE rather than alongside `drift` in decisions.mts purely because that
 * file is at its 500-line cap; `categories` set the precedent for a plain-function command living at
 * this layer.
 */

import { randomUUID } from 'node:crypto';
import { readdirSync } from 'node:fs';
import { resolveFromCwd, resolveGuardConfig } from '../config.mts';
import { emitGateEvent } from '../judge/gate-events.mts';
import { clip } from '../judge/odb-probe.mts';
import { markGateRun } from '../judge/run-context.mts';
// Type-only: erased at compile, so naming the envelope here does NOT re-link decisions.mts — the
// module that is unloadable in exactly the case this file has to answer for.
import type { QueryEnvelope } from './decisions.mts';

/**
 * Sub-engines load dynamically so a missing parser is catchable, and only via STRING LITERALS so the
 * dist rewrite and dist-integrity both see them. Why: decision-retrieval-candidate-set (sc-2692).
 */

// Dev runs the .mts source (Node strips types); the shipped dist is compiled .mjs. Derive the
// runtime extension from THIS module so the sub-engine URLs resolve in both.
const SELF_EXT = import.meta.url.endsWith('.mts') ? '.mts' : '.mjs';
const SUB_ENGINES: Record<string, URL> = {
  detect: new URL(`./detect${SELF_EXT}`, import.meta.url),
  'check-alignment': new URL(`./check-alignment${SELF_EXT}`, import.meta.url),
  'scoped-targets': new URL(`./scoped-targets${SELF_EXT}`, import.meta.url),
  enforce: new URL(`./ruling-checks/enforce${SELF_EXT}`, import.meta.url),
};

/** An agent's reads of the log. Each is its own agent run, so no `git write-tree` and no commit row. */
const AGENT_READS = new Set(['show', 'query', 'scoped-targets']);

function flagValue(args: string[], name: string): string | undefined {
  const i = args.indexOf(name);
  return i === -1 ? undefined : args[i + 1];
}

/** Only show and query are logged: an older synced hook's scoped-targets calls write nothing. */
function emitDecisionRead(cmd: string | undefined, rest: string[]) {
  if (cmd === 'show') emitGateEvent({ type: 'decision_read', command: 'show', slugs: [rest[0]] });
  if (cmd !== 'query') return;
  const top = Number.parseInt(flagValue(rest, '--top') ?? '', 10);
  emitGateEvent({ type: 'decision_read', command: 'query', top: top > 0 ? top : 5 });
}

async function run(argv: string[]) {
  const [cmd, ...rest] = argv;
  if (AGENT_READS.has(cmd)) process.env.DEVKIT_AGENT_RUN_ID ||= `decisions-${randomUUID()}`;
  if (cmd === 'categories') {
    // recall/category-report.mts's import closure never reaches markdown.mts, so this command works
    // on a tree with no mdast installed. It only ever failed because of the static link above.
    const { cmdCategories } = await import('./recall/category-report.mts');
    cmdCategories();
    return;
  }
  if (cmd === 'integrity') {
    // A non-zero scan is a finding, not a crash — set exitCode rather than throwing into the
    // catch below, which would relabel it as `guard-decisions: <error>`.
    // --staged is the commit-time gate: same checks, scoped to this change and diffed against HEAD.
    // Bare `integrity` keeps its whole-corpus contract, known historical finding included.
    process.exitCode = rest.includes('--staged')
      ? (await import('./integrity/staged-gate.mts')).runStagedIntegrity()
      : (await import('./integrity/scan.mts')).cmdIntegrity();
    return;
  }
  const sub = SUB_ENGINES[cmd];
  if (sub) {
    // The hook runs only `detect --gate`; check-alignment is an on-demand run and stays unmarked.
    if (cmd === 'detect' && rest[0] === '--gate') markGateRun();
    await (await import(sub.href)).main(rest);
    return;
  }
  const { main: decisionsMain } = await import('./decisions.mts');
  await decisionsMain(argv);
  emitDecisionRead(cmd, rest);
}

/** The one string a caller can grep for to tell an outage from an answer. */
const UNAVAILABLE_MARKER = 'decision engine UNAVAILABLE';

/** Commands that ANSWER from the log, where an outage is mistakable for "nothing rules on this".
 * Every other command fails visibly on its own terms and needs no retrieval caveat. */
const RETRIEVAL_COMMANDS = new Set(['query', 'scoped-targets']);

/**
 * The dependency an unloadable engine named, else null. Positive-signal-only: anything but
 * ERR_MODULE_NOT_FOUND stays an ordinary error (judge-outage-classified-not-blocked).
 */
function missingModule(error: Error): string | null {
  // SAFETY: Node module-resolution failures carry ErrnoException.code; an absent field fails below.
  const { code } = error as NodeJS.ErrnoException;
  if (code !== 'ERR_MODULE_NOT_FOUND') return null;
  const named = /Cannot find (?:package|module) '([^']+)'/.exec(error.message);
  return named?.[1] ?? 'a required dependency';
}

/**
 * Axis FILENAMES, alphabetical and deliberately unranked — never record content.
 * Why both: decision-format-parsed-not-regexed, and the note on decision-retrieval-candidate-set.
 */
function axisSlugs(): string[] | null {
  try {
    const dir = resolveFromCwd(resolveGuardConfig(process.cwd()), 'decisionsDir');
    return dir == null
      ? null
      : readdirSync(dir)
          .filter((f) => f.endsWith('.md') && f !== 'INDEX.md')
          .map((f) => f.slice(0, -3))
          .sort();
  } catch {
    return null;
  }
}

/**
 * Built HERE because decisions.mts is the module that failed. `rows: []` keeps a rows-only consumer
 * at "abstained". Field-by-field reasoning: the sc-2692 note on decision-retrieval-candidate-set.
 */
const UNAVAILABLE_ENVELOPE: QueryEnvelope = {
  state: 'UNAVAILABLE',
  source: 'unavailable',
  tau: null,
  margin: null,
  rows: [],
  cost: { llmCalls: 0, ms: 0 },
};

/** Say what did not happen, then hand over the manual route. Everything here goes to STDERR. */
function reportUnavailable(dependency: string, cmd: string | undefined) {
  console.error(
    `guard-decisions: ${UNAVAILABLE_MARKER} — could not load ('${dependency}' is not installed).`,
  );
  console.error("Remedy: install this package's dependencies (e.g. `bun install`), then re-run.");
  // Only a command that ANSWERS from the log can have its outage misread as an empty answer, so
  // only those get the caveat and the manual route. `integrity` failing is just a failure.
  if (!RETRIEVAL_COMMANDS.has(cmd ?? '')) return;
  console.error(
    'Nothing was searched. This is NOT "no governing Target", and must not be read as one.',
  );

  const slugs = axisSlugs();
  if (slugs == null) {
    console.error(
      'The decisions directory could not be resolved either — check guard.config.json.',
    );
    return;
  }
  if (slugs.length === 0) {
    console.error('The decisions directory is empty: nothing has been recorded.');
    return;
  }
  const noun = slugs.length === 1 ? 'axis' : 'axes';
  console.error(`\nRead the log by hand. ${slugs.length} ${noun}, ALPHABETICAL — not a ranking:`);
  for (const slug of slugs) console.error(`  ${slug}`);
  console.error(
    '\n  1. INDEX.md in that directory — the rendered spine (a view, and it can omit axes)',
  );
  console.error('  2. cat <decisionsDir>/<slug>.md');
  console.error(
    "  3. grep -n '^## ' <decisionsDir>/<slug>.md — a LATER `## Target ·` block supersedes an earlier one",
  );
}

const argv = process.argv.slice(2);

run(argv).catch((error) => {
  // Narrowed as gate-engine/structure/load-baseline.mts does: a non-Error throw carries no code.
  const dependency = error instanceof Error ? missingModule(error) : null;
  if (dependency) {
    reportUnavailable(dependency, argv[0]);
    if (argv.includes('--brief')) {
      const file = clip(flagValue(argv, '--files') ?? '');
      emitGateEvent({ type: 'brief_unavailable', file, reason: 'unloadable', dependency });
    }
    // --json gets the envelope; every other invocation leaves stdout EMPTY, because a `[]` here is
    // exactly how an outage gets read as "nothing governs".
    if (argv[0] === 'query' && argv.includes('--json')) {
      process.stdout.write(`${JSON.stringify(UNAVAILABLE_ENVELOPE, null, 2)}\n`);
    }
    // exitCode, not process.exit (which can truncate a piped stdout). 1 not 3, per
    // gate-opt-out-is-visible-and-detectable: this is a local, reproducible could-not-run.
    process.exitCode = 1;
    return;
  }
  console.error(`guard-decisions: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
});

