/**
 * Best-effort append-only telemetry sink for `devkit ship`/`reship` gate events. Mirrors
 * progress.mts (env-keyed, fs-only, never throws) and lives in the judge domain for the same reason
 * verdict-store.mts does: it is a shared side-channel service every verdict-producing engine
 * (deterministic, decisions, review) depends on — one emitter here, not a vendored copy per engine.
 *
 * A ship exports DEVKIT_GATE_EVENTS (sink path) + DEVKIT_SHIP_ID (correlates every gate/reviewer
 * event of one ship attempt) through the hook chain — the SAME inheritance path git→husky→node that
 * carries DEVKIT_REVIEW_PROGRESS — so each in-chain gate stamps the same ship_id. When that env is
 * unset (an ad-hoc commit, not a ship) events still land, in the default ~/.devkit/telemetry sink
 * that telemetrySink() supplies; DEVKIT_NO_TELEMETRY=1 is what makes emit a no-op.
 *
 * Failure direction: any IO error is swallowed — telemetry must NEVER fail a gate. Each event is one
 * JSON line appended with a single O_APPEND write, so concurrent judges can't tear each other's lines
 * (sub-4KB writes are atomic on APFS/ext4). The downstream reader (the usage tracker's collector)
 * tail-ingests this file and skips/retries any partial trailing line.
 */
import { appendFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';
import { runEnvelope, telemetrySink } from './run-context.mts';

/**
 * Append one gate/reviewer/ship event to the telemetry sink (no-op when there is none). The sink is
 * the ship's DEVKIT_GATE_EVENTS, or — by default for every commit, unless DEVKIT_NO_TELEMETRY=1 — the
 * default ~/.devkit/telemetry sink. runEnvelope() stamps the correlation id (ship_id) plus, for a
 * commit run, run_mode/repo/branch so the collector can synthesise a run. Never throws.
 */
/**
 * A cache hit is a gate's cheapest and most INVISIBLE outcome: no judge runs, so neither a
 * judge_exec nor a *_result event is emitted, and the run reads downstream exactly as though that
 * judge had never been selected. The hit RATE was therefore unmeasurable — the one number any
 * judgement-cache change has to be sized against, and the number sc-1239 was filed on a bad
 * estimate of (its "9.4%" was reviewer PROSE containing the word "caching").
 *
 * `judge` uses the SAME labels as judge_exec (`review:<reviewer>`, `review:completeness`,
 * `decision-alignment`), so a reader gets the rate as cache_hit / (cache_hit + judge_exec) grouped
 * by judge, with no join. Deliberately its own event type rather than a synthetic `*_result` row:
 * that would inflate the fail-rate denominator and flatten the duration percentiles read off the
 * very same rows any follow-up has to size itself against.
 */
export function emitCacheHit(judge: string, model?: unknown, durationMs?: unknown): void {
  emitGateEvent({
    type: 'cache_hit',
    judge,
    ...(model ? { model } : {}),
    ...(typeof durationMs === 'number' && Number.isFinite(durationMs)
      ? { duration_ms: Math.max(0, Math.round(durationMs)) }
      : {}),
  });
}

/** A review-gate hit, which also names the base its PASS was judged against (sc-3468). */
export interface ReviewCacheHit {
  judge: string;
  model: string | undefined;
  durationMs: number;
  /** The single earlier base the PASS was judged on; null when current, unknown, or several. */
  judgedBaseSha: string | null;
  /** current | moved-clear | moved-overlap | unknown — the digest demotes only the last two. */
  baseState: string;
  /** evidence_* coverage of the packet the PASS was judged on; {} when complete (sc-2305). */
  coverage?: object;
  /** The waived findings the replayed PASS rests on; omitted when there are none. */
  waivers?: { lens: string; fingerprint: string }[];
}

/** cache_hit for a domain reviewer. Other emitters keep emitCacheHit, whose rows carry no base
 * fields, and the digest reads an absent field as "this cache key covers the tree". */
export function emitReviewCacheHit(hit: ReviewCacheHit): void {
  emitGateEvent({
    type: 'cache_hit',
    judge: hit.judge,
    // JSON.stringify drops an undefined field, so an unknown model is omitted, not blank.
    model: hit.model || undefined,
    duration_ms: Math.max(0, Math.round(hit.durationMs)),
    judged_base_sha: hit.judgedBaseSha,
    base_state: hit.baseState,
    ...hit.coverage,
    // Omitted, like an unknown model, when the PASS rests on no waiver.
    waivers: hit.waivers?.length ? hit.waivers : undefined,
  });
}

/** A hit on a cache key that does NOT hash the evidence bytes (sc-3175). */
export interface IntentCacheHit {
  judge: string;
  model: string;
  durationMs: number | undefined;
  /** Whether the staged diff is the one the cached verdict was judged on. */
  diffMatches: boolean;
}

/** cache_hit for completeness's branch+message sticky key, which a reshaped diff can reuse. Same
 * row and label per Ruling (3); byte-keyed callers keep emitCacheHit, which covers the diff. */
export function emitIntentCacheHit(hit: IntentCacheHit): void {
  emitGateEvent({
    type: 'cache_hit',
    judge: hit.judge,
    // JSON.stringify drops an undefined field, so an unknown model or duration is omitted, not blank.
    model: hit.model || undefined,
    duration_ms: hit.durationMs === undefined ? undefined : Math.max(0, Math.round(hit.durationMs)),
    scope: 'intent',
    diff_matches: hit.diffMatches,
  });
}

/** Cache-aware wall-clock summary for one serial or bounded-parallel gate stage. */
export function emitGateTiming(
  gate: string,
  actualDurationMs: number,
  effectiveDurationMs: number,
  cacheState: 'none' | 'partial' | 'full',
  parallelism = 1,
): void {
  emitGateEvent({
    type: 'gate_timing',
    gate,
    actual_duration_ms: Math.max(0, Math.round(actualDurationMs)),
    effective_duration_ms: Math.max(0, Math.round(effectiveDurationMs)),
    cache_state: cacheState,
    parallelism: Math.max(1, Math.floor(parallelism)),
  });
}

/** Emit a serial gate's timing and preserve its caller's exit-code contract. */
export function finishGateTiming(
  gate: string,
  startedAt: number,
  code: number,
  cacheState: 'none' | 'partial' | 'full' = 'none',
  effectiveDurationMs?: number,
): number {
  const actualDurationMs = Date.now() - startedAt;
  emitGateTiming(
    gate,
    actualDurationMs,
    Math.max(actualDurationMs, effectiveDurationMs ?? actualDurationMs),
    cacheState,
  );
  return code;
}

/**
 * A gate that COULD NOT RUN produced no outcome, so it gets its own event type rather than a
 * synthetic `gate_result` row — Ruling (3) of the gate-telemetry-self-describing Target, whose
 * stated reason is that a synthetic row "inflates that event's fail-rate denominator and flattens
 * the duration percentiles read off the very same rows".
 *
 * sc-1366: an object-database fault emitted NOTHING at all, so it was invisible in the event
 * stream and cost the same investigation twice. `fault` distinguishes the gate's view from ship's
 * `staged_objects_missing` (cli/lib/ship/commit-with-gate-capture.sh): ship inherits the caller's
 * git environment while gates are spawned through __dk_no_git_env, so "ship says readable + gate
 * says unreadable" is the evidence that separates a deletion from a split object database. One
 * shared token would erase it.
 */
export function emitGateInfraFailure(ev: Record<string, unknown> & { gate: string }): void {
  emitGateEvent({ type: 'gate_infra_failure', ...ev });
}

/**
 * A DELIBERATE per-run gate bypass (a GUARD_* flag the operator exported). One shared emitter so
 * every bypass is countable on the structured `bypass` field instead of grepping ad-hoc `detail`
 * encodings — and so new bypasses keep `status: 'could_not_run'`, the deterministic gate's ruled
 * precedent: a bypassed gate verified nothing, and a status downstream readers would treat as
 * clean is what Ruling (3) of gate-telemetry-self-describing forbids inventing. (coverage's
 * pre-existing `status: 'bypassed'` row keeps its shape for continuity and gains the same field.)
 */
export function emitGateBypass(gate: string, flag: string): void {
  emitGateEvent({
    type: 'gate_result',
    gate,
    status: 'could_not_run',
    bypass: flag,
    detail: `${gate}(bypassed:${flag})`,
  });
}

/** What became of one event line, so a caller can report a dark or failed sink, never guess. */
export type TelemetryStatus = 'written' | 'disabled' | 'failed';

export function emitGateEvent<Fields extends object>(ev: Fields): TelemetryStatus {
  const file = telemetrySink();
  if (!file) return 'disabled';
  try {
    mkdirSync(path.dirname(file), { recursive: true });
    const line = `${JSON.stringify({
      ...ev,
      ...runEnvelope(),
      ts: new Date().toISOString(),
    })}\n`;
    appendFileSync(file, line, { flag: 'a' });
    return 'written';
  } catch {
    /* telemetry is best-effort — never fail a gate over it */
    return 'failed';
  }
}

